              query: {type: 'not-a-json-schema-type'},
            },
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_lookup/);
  });

  it('rejects input missing a required field with a ToolResponse and never invokes the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({
      executorCalls,
      mentionsLocationAsRequired: response.result.includes('location') && /required/i.test(response.result),
    }).toEqual({
      executorCalls: 0,
      mentionsLocationAsRequired: true,
    });
  });

  it('rejects a wrong-typed field naming the path and expected type without leaking the value in result or logs', async () => {
    const recordedLogs: string[] = [];
    const recordLine = (category: string, message: string, fields?: Record<string, unknown>) => {
      recordedLogs.push(JSON.stringify({category, message, fields}));
    };
    const logger: Logger = {
      debug: recordLine,
      info: recordLine,
      warn: recordLine,
      error: recordLine,
    };
    setLogger(logger);

    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'lookup_patient',
        description: 'Look up a patient by identifier',
        inputSchema: {
          type: 'object',
          properties: {patientId: {type: 'string'}},
          required: ['patientId'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('lookup_patient', {patientId: 987654321});

    expect({
      executorCalls,
      mentionsPath: response.result.includes('patientId'),
      mentionsType: response.result.includes('string'),
      leaksInResult: response.result.includes('987654321'),
      leaksInLogs: recordedLogs.some(line => line.includes('987654321')),
    }).toEqual({
      executorCalls: 0,
      mentionsPath: true,
      mentionsType: true,
      leaksInResult: false,
      leaksInLogs: false,
    });
  });

  it('passes valid input with an unlisted extra property through to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    const receivedInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'},
            units: {type: 'string', enum: ['celsius', 'fahrenheit'], default: 'celsius'},
          },
          required: ['location'],
        },
      },
      async input => {
        receivedInputs.push(input);
        return 'sunny';
      }
    );

    await registry.execute('get_weather', {location: 'Berlin', extraKey: 42});

    expect(receivedInputs).toEqual([{location: 'Berlin', extraKey: 42}]);
  });

  it('throws Unknown tool for an unregistered tool name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('missing_tool', {})).rejects.toThrow('Unknown tool: missing_tool');
  });

  it('compiles a static tool schema once at register time and reuses it across ten execute calls', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    const schema: Record<string, unknown> = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const definition = {
      name: 'get_weather',
      description: 'Get weather for a location',
      get inputSchema(): Record<string, unknown> {
        schemaReads += 1;
        return schema;
      },
    };

    registry.register(definition, async () => 'sunny');
    for (let i = 0; i < 10; i++) {
      await registry.execute('get_weather', {location: 'Berlin'});
    }

    expect(schemaReads).toBe(1);
  });

  it('validates a function-valued tool definition against the schema returned for the current call', async () => {
    const registry = new ToolRegistry();
    let requiredProp = 'city';
    registry.register(
      () => ({
        name: 'dynamic_lookup',
        description: 'Tool whose schema changes between calls',
        inputSchema: {
          type: 'object',
          properties: {
            city: {type: 'string'},
            country: {type: 'string'},
          },
          required: [requiredProp],
        },
      }),
      async () => 'ok'
    );

    const firstCall = await registry.execute('dynamic_lookup', {city: 'Paris'});
    requiredProp = 'country';
    const secondCallMissingCountry = await registry.execute('dynamic_lookup', {city: 'Paris'});
    const thirdCallWithCountry = await registry.execute('dynamic_lookup', {country: 'France'});

    expect({
      firstResult: firstCall.result,
      secondMentionsCountry:
        secondCallMissingCountry.result.includes('country') && /required/i.test(secondCallMissingCountry.result),
      thirdResult: thirdCallWithCountry.result,
    }).toEqual({
      firstResult: 'ok',
      secondMentionsCountry: true,
      thirdResult: 'ok',
    });
  });
});

