    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates `input` against `inputSchema` (returning a rejection `ToolResponse`) and throws only on an unknown tool — see `specs/hal-engine-tool-input-validation/spec.md`. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validator = this.resolveValidator(name, tool);
    if (!validator(input)) {
      const errors = formatValidationErrors(validator.errors);
      log.warn('tool', 'invalid input', {name, errors});
      return {result: `Invalid input for tool "${name}": ${errors.join('; ')}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private resolveValidator(name: string, tool: StoredTool): ValidateFunction {
    if (tool.validateInput) return tool.validateInput;
    const {inputSchema} = this.resolveDefinition(tool.definitionSource);
    const cached = this.schemaValidators.get(inputSchema);
    if (cached) return cached;
    const compiled = compileSchema(name, inputSchema);
    this.schemaValidators.set(inputSchema, compiled);
    return compiled;
  }
}

const ajv = new AjvConstructor({strict: false, validateFormats: false, allErrors: true});

function compileSchema(toolName: string, schema: Record<string, unknown>): ValidateFunction {
  try {
    return ajv.compile(schema);
  } catch (error) {
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${(error as Error).message}`, {cause: error});
  }
}

function formatValidationErrors(errors: ErrorObject[] | null | undefined): string[] {
  if (!errors || errors.length === 0) return ['input does not match schema'];
  return errors.map(formatValidationError);
}

function formatValidationError(error: ErrorObject): string {
  const path = error.instancePath ? error.instancePath.slice(1).replace(/\//g, '.') : '';
  if (error.keyword === 'required') {
    const missing = String((error.params as {missingProperty?: unknown}).missingProperty ?? '');
    const fullPath = path ? `${path}.${missing}` : missing;
    return `missing required property "${fullPath}"`;
  }
  const target = path || 'input';
  return `${target} ${error.message ?? `failed ${error.keyword} check`}`;
}

